  - exact bootq_1RB1LC_0LC0RB_1LA1RD_0LD0LB.
  - intros p _. apply lap_1RB1LC_0LC0RB_1LA1RD_0LD0LB.
  - intros t Ht p _. apply fire_1RB1LC_0LC0RB_1LA1RD_0LD0LB. exact Ht.
  - exact wit_1RB1LC_0LC0RB_1LA1RD_0LD0LB.
  - apply qcleb_QE_05. reflexivity.
