  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LC0RB_1LA1RD_0LD0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LC0RB_1LA1RD_0LD0RC p j E)].
