  - exact bootq_1RB1LC_0LC0RB_1LA1RD_0LD0RC.
  - intros p _. apply lap_1RB1LC_0LC0RB_1LA1RD_0LD0RC.
  - intros t Ht p _. apply fire_1RB1LC_0LC0RB_1LA1RD_0LD0RC. exact Ht.
