  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_0LC0RB_1LA1RD_0RC0LD
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LC0RB_1LA1RD_0RC0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
